<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { api } from '../api/client'
const data=ref<any>({revision:0,rules:[]}); const state=ref('free'); const kind=ref('weekly'); const start=ref('18:00'); const end=ref('22:00'); const day=ref(new Date().toISOString().slice(0,10)); const weekdays=ref([1,2,3,4,5]); const saved=ref(''); const error=ref(''); const shareText=ref(''); const preview=ref<any>(); const label=ref('我的课表')
const weekdayNames=['一','二','三','四','五','六','日']; onMounted(load)
async function load(){data.value=await api('/me/availability')}
async function save(){error.value='';try{const rule=kind.value==='weekly'?{state:state.value,source:'weekly',kind:'weekly',recurrence:{weekdays:weekdays.value,start_time:start.value,end_time:end.value,valid_from:new Date().toISOString().slice(0,10),valid_until:new Date(Date.now()+180*86400000).toISOString().slice(0,10),timezone:'Asia/Shanghai'}}:{state:state.value,source:'one_off',kind:'once',start_at:`${day.value}T${start.value}:00+08:00`,end_at:`${day.value}T${end.value}:00+08:00`};await api('/me/availability/rules',{method:'POST',body:JSON.stringify({rules:[rule],expected_revision:data.value.revision})});await load();saved.value='已保存';setTimeout(()=>saved.value='',1600)}catch(e){error.value=e instanceof Error?e.message:'保存失败'}}
async function remove(id:string){await api(`/me/availability/rules/${id}?expected_revision=${data.value.revision}`,{method:'DELETE'});await load()}
async function previewImport(){error.value='';try{preview.value=await api('/me/imports/wakeup/preview',{method:'POST',body:JSON.stringify({share_text:shareText.value})})}catch(e){error.value=e instanceof Error?e.message:'导入失败'}}
async function confirmImport(){await api('/me/imports/wakeup/confirm',{method:'POST',body:JSON.stringify({preview_id:preview.value.preview_id,label:label.value,baseline_rules:[],expected_revision:data.value.revision})});preview.value=null;shareText.value='';await load();saved.value='课表已导入'}
</script>
<template><section class="shell page"><div class="page-head"><div><p class="eyebrow">我的时间</p><h1>什么时候可以约球</h1><p class="muted">空白保持未知；活动只把你完整标为空闲的时段计入推荐。</p></div><button class="primary" @click="save">保存时间</button></div><div class="time-layout"><div class="stack"><article class="card stack"><div class="segmented"><button :class="{selected:kind==='weekly'}" @click="kind='weekly'">每周重复</button><button :class="{selected:kind==='once'}" @click="kind='once'">指定日期</button></div><label v-if="kind==='once'">日期<input v-model="day" type="date"></label><fieldset v-else><legend>星期</legend><div class="weekday"><label v-for="(name,index) in weekdayNames" :key="name"><input v-model="weekdays" type="checkbox" :value="index+1">周{{name}}</label></div></fieldset><div class="form-grid"><label>开始<input v-model="start" type="time" step="900"></label><label>结束<input v-model="end" type="time" step="900"></label></div><fieldset><legend>这段时间</legend><div class="segmented state"><button :class="{selected:state==='free'}" @click="state='free'">空闲</button><button :class="{selected:state==='busy'}" @click="state='busy'">繁忙</button><button :class="{selected:state==='unknown'}" @click="state='unknown'">未知</button></div></fieldset><p v-if="saved" class="saved">{{ saved }}</p><p v-if="error" class="error">{{ error }}</p></article><article class="card stack"><div><p class="eyebrow">WAKEUP 导入</p><h2>从分享口令导入课程</h2><p class="muted">口令只用于这次导入，不会保存或持续同步。</p></div><label>完整分享文字或口令<textarea v-model="shareText" rows="3" autocomplete="off"></textarea></label><button :disabled="!shareText.trim()" @click="previewImport">先查看预览</button><div v-if="preview" class="preview"><strong>{{ preview.summary.course_count }} 门课程 · {{ preview.summary.occurrence_count }} 个繁忙区间</strong><p>{{ preview.term.start }} 至 {{ preview.term.end }}</p><label>课表名称<input v-model="label"></label><button class="primary" @click="confirmImport">使用这份课表</button></div></article></div><aside class="card"><h2>已保存规则</h2><div v-if="data.rules.length" class="rule-list"><div v-for="rule in data.rules" :key="rule.id" class="rule"><div><span class="badge">{{rule.state==='free'?'空闲':rule.state==='busy'?'繁忙':'未知'}}</span><p>{{ rule.kind==='weekly'?'每周重复':'一次性' }} · {{ rule.source }}</p></div><button v-if="rule.source!=='course'" aria-label="删除规则" @click="remove(rule.id)">删除</button></div></div><p v-else class="muted">还没有明确的时间规则。</p></aside></div><div class="mobile-action"><button class="primary" @click="save">{{ saved||'保存时间' }}</button></div></section></template>
<style scoped>.time-layout{display:grid;grid-template-columns:minmax(0,2fr) minmax(260px,1fr);gap:20px}.segmented{display:grid;grid-template-columns:repeat(2,1fr);gap:6px;background:var(--unknown);padding:4px;border-radius:12px}.segmented button{border:0;background:transparent}.segmented .selected{background:white;color:var(--primary);box-shadow:0 1px 3px rgba(0,0,0,.08)}.segmented.state{grid-template-columns:repeat(3,1fr)}fieldset{border:0;padding:0;margin:0}legend{font-size:14px;font-weight:620;margin-bottom:8px}.weekday{display:flex;flex-wrap:wrap;gap:6px}.weekday label{display:flex;align-items:center;gap:5px;border:1px solid var(--line);padding:8px;border-radius:9px}.weekday input{min-height:auto;width:auto}.saved{color:var(--primary);font-weight:650}.rule{display:flex;justify-content:space-between;align-items:center;border-top:1px solid var(--line);padding:12px 0}.rule p{margin:5px 0 0;font-size:13px;color:var(--muted)}.rule button{min-height:36px}.preview{border-left:3px solid var(--primary);padding-left:14px}@media(max-width:720px){.time-layout{grid-template-columns:1fr}.time-layout aside{order:-1}}</style>

